package aulas.umc.oo.UseCase;
import aulas.umc.oo.DTO.*; import aulas.umc.oo.mapper.ClienteMapper; import aulas.umc.oo.model.Cliente; import aulas.umc.oo.repository.ClienteRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ClienteUseCase { private final ClienteRepository repo; private final ClienteMapper mapper; public ClienteUseCase(ClienteRepository r,ClienteMapper m){repo=r;mapper=m;} public ClienteResponse criar(ClienteRequest r){return mapper.toResponse(repo.insert(mapper.toDomain(r)));} public List<ClienteResponse> listar(){return repo.findAll().stream().map(mapper::toResponse).toList();} public ClienteResponse buscar(UUID id){return mapper.toResponse(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Cliente nao encontrado")));} public ClienteResponse atualizar(UUID id,ClienteRequest r){Cliente c=mapper.toDomain(r);c.id=id;return mapper.toResponse(repo.update(c));} public void excluir(UUID id){repo.deleteLogical(id);} }
